/* rt_mods.c - N-Gage additions layered on the original game.
 *
 * 1. Button prompts: the cartridge's circled A/B glyphs are redrawn as the
 *    N-Gage keys (5 / 7) right after the game decompresses the tilesets
 *    that contain them (table generated by tools/find_prompts.py).
 * 2. Title menu "Exit": see rt_exit.c.
 */
#include <string.h>

#include "rt.h"
#include "rt_mem.h"
#include "rt_ngage.h"

typedef struct { u32 src; u32 offset; u8 high; u8 value; } rt_prompt_edit;
extern const rt_prompt_edit g_rt_prompt_edits[];

int g_rt_ngage_prompts = 1;

/* Button tiles (rt_buttons_data.c): any 8x8 tile equal to a cartridge
 * button glyph becomes its N-Gage redraw, wherever it was decompressed. */
typedef struct { u8 from[32]; u8 to[32]; } rt_button_tile;
extern const rt_button_tile g_rt_button_tiles[];
extern const u32 g_rt_button_tile_count;

#define BTN_HASH 64u
static s16 s_btn_head[BTN_HASH], s_btn_next[256];
static int s_btn_ready;

/* hash of a whole tile (8 words) */
static u32 btn_key8(const u32 *w)
{
    u32 h = 0, i;
    for (i = 0; i < 8u; i++) h = (h ^ w[i]) * 2654435761u;
    return h >> 26;
}

static void btn_init(void)
{
    u32 i;
    for (i = 0; i < BTN_HASH; i++) s_btn_head[i] = -1;
    for (i = 0; i < g_rt_button_tile_count && i < 256u; i++) {
        const u8 *f = g_rt_button_tiles[i].from;
        u32 w[8], j, k;
        for (j = 0; j < 8u; j++)
            w[j] = (u32)f[j * 4] | ((u32)f[j * 4 + 1] << 8) | ((u32)f[j * 4 + 2] << 16) | ((u32)f[j * 4 + 3] << 24);
        k = btn_key8(w);
        s_btn_next[i] = s_btn_head[k];
        s_btn_head[k] = (s16)i;
    }
    s_btn_ready = 1;
}

typedef struct { u8 ntiles; u8 from[128]; u8 to[128]; } rt_button_group;
extern const rt_button_group g_rt_button_groups[];

/* 16x16 sprite buttons whose tiles two buttons share (a bobbing frame of
 * the dress-up prompts): before each frame, a sprite whose four tiles are
 * each the button's cartridge or redrawn tile gets the whole redraw. */
static void btn_fix_groups(void)
{
    u32 i, oned = (RT_IO16(0) >> 6) & 1u;
    if (!g_rt_button_groups[0].ntiles || !g_rt_ngage_prompts) return;
    for (i = 0; i < 128u; i++) {
        u32 a0 = LD16(0x07000000u + i * 8u), a1 = LD16(0x07000002u + i * 8u), a2 = LD16(0x07000004u + i * 8u);
        u32 base, addr[4], k;
        const rt_button_group *g;
        if ((a0 & 0x300u) == 0x200u || (a0 & 0x2000u)) continue;   /* hidden, 8bpp */
        if ((a0 >> 14) != 0u || (a1 >> 14) != 1u) continue;        /* 16x16 only */
        base = 0x06010000u + (a2 & 0x3FFu) * 32u;
        addr[0] = base;
        addr[1] = base + 32u;
        addr[2] = base + (oned ? 64u : 0x400u);
        addr[3] = addr[2] + 32u;
        for (g = g_rt_button_groups; g->ntiles; g++) {
            int need = 0;
            for (k = 0; k < 4u; k++) {
                u32 j, isf = 1, ist = 1;
                for (j = 0; j < 32u && (isf || ist); j++) {
                    u32 v = LD8(addr[k] + j);
                    if (v != g->from[k * 32u + j]) isf = 0;
                    if (v != g->to[k * 32u + j]) ist = 0;
                }
                if (!isf && !ist) break;
                if (!ist) need = 1;
            }
            if (k < 4u) continue;
            if (need)
                for (k = 0; k < 4u; k++) {
                    u32 j;
                    for (j = 0; j < 32u; j += 2u)
                        ST16(addr[k] + j, (u32)g->to[k * 32u + j] | ((u32)g->to[k * 32u + j + 1u] << 8));
                }
            break;
        }
    }
}

static void btn_patch(u32 dst, u32 size)
{
    u32 t;
    if (!s_btn_ready) btn_init();
    for (t = 0; t + 32u <= size; t += 32u) {
        u32 a = dst + t, w[8], j, nz = 0;
        s32 i;
        for (j = 0; j < 8u; j++) nz |= (w[j] = LD32(a + j * 4u));
        if (!nz) continue;
        for (i = s_btn_head[btn_key8(w)]; i >= 0; i = s_btn_next[i]) {
            const rt_button_tile *b = &g_rt_button_tiles[i];
            u32 j;
            for (j = 0; j < 32u && LD8(a + j) == b->from[j]; j++) {}
            if (j < 32u) continue;
            for (j = 0; j < 32u; j += 2u) ST16(a + j, (u32)b->to[j] | ((u32)b->to[j + 1] << 8));
            break;
        }
    }
}

/* Buttons drawn as an OBJ plus its horizontally flipped twin share tiles, so
 * an (asymmetric) key digit cannot be drawn into them.  Before each frame,
 * a flipped OBJ showing a redrawn button half is pointed at spare OBJ tiles
 * (all zero, not used by any OBJ this frame) holding the right half. */
typedef struct { u8 w, h; u8 left[64]; u8 right[64]; } rt_button_mirror;
extern const rt_button_mirror g_rt_button_mirrors[];

static int vram_tile_is(u32 tile, const u8 *data)
{
    u32 j, a = 0x06010000u + (tile & 0x3FFu) * 32u;
    for (j = 0; j < 32u; j++)
        if (LD8(a + j) != data[j]) return 0;
    return 1;
}

static int vram_tile_zero(u32 tile)
{
    u32 j, a = 0x06010000u + (tile & 0x3FFu) * 32u;
    for (j = 0; j < 32u; j += 4u)
        if (LD32(a + j)) return 0;
    return 1;
}

static void btn_split_mirrors(void)
{
    static const u8 dims[3][4][2] = {
        { { 1, 1 }, { 2, 2 }, { 4, 4 }, { 8, 8 } },
        { { 2, 1 }, { 4, 1 }, { 4, 2 }, { 8, 4 } },
        { { 1, 2 }, { 1, 4 }, { 2, 4 }, { 4, 8 } } };
    static u8 used[1024 / 8];
    int map1d = (LD16(0x04000000u) & 0x40u) != 0, any = 0;
    u32 i;
    const rt_button_mirror *m;
    if (!g_rt_button_mirrors[0].w || !g_rt_ngage_prompts) return;
    for (i = 0; i < 128u; i++) {
        u32 a1 = LD16(0x07000002u + i * 8u);
        if (a1 & 0x1000u) { any = 1; break; }
    }
    if (!any) return;
    /* tiles used by any OBJ this frame */
    memset(used, 0, sizeof used);
    for (i = 0; i < 128u; i++) {
        u32 a0 = LD16(0x07000000u + i * 8u), a1 = LD16(0x07000002u + i * 8u), a2 = LD16(0x07000004u + i * 8u);
        u32 sh = a0 >> 14, sz = a1 >> 14, tx, ty;
        if (sh == 3u || (a0 & 0x300u) == 0x200u) continue;
        for (ty = 0; ty < dims[sh][sz][1]; ty++)
            for (tx = 0; tx < dims[sh][sz][0]; tx++) {
                u32 t = ((a2 & 0x3FFu) + ty * (map1d ? dims[sh][sz][0] : 32u) + tx) & 0x3FFu;
                used[t >> 3] |= (u8)(1u << (t & 7u));
            }
    }
    for (i = 0; i < 128u; i++) {
        u32 a0 = LD16(0x07000000u + i * 8u), a1 = LD16(0x07000002u + i * 8u), a2 = LD16(0x07000004u + i * 8u);
        u32 sh = a0 >> 14, sz = a1 >> 14;
        if (!(a1 & 0x1000u) || (a0 & 0x300u) || sh == 3u) continue;
        for (m = g_rt_button_mirrors; m->w; m++) {
            u32 n = (u32)m->w * m->h, k, t, cand;
            if (dims[sh][sz][0] != m->w || dims[sh][sz][1] != m->h) continue;
            for (k = 0; k < n; k++) {
                t = (a2 & 0x3FFu) + (k / m->w) * (map1d ? m->w : 32u) + k % m->w;
                if (!vram_tile_is(t, m->left + k * 32u)) break;
            }
            if (k < n) continue;
            /* spare tiles, searched from the top of OBJ VRAM */
            for (cand = 1024u - n * (map1d ? 1u : 32u); cand > 512u; cand--) {
                for (k = 0; k < n; k++) {
                    t = (cand + (k / m->w) * (map1d ? m->w : 32u) + k % m->w) & 0x3FFu;
                    if ((used[t >> 3] >> (t & 7u)) & 1u) break;
                    if (!vram_tile_zero(t) && !vram_tile_is(t, m->right + k * 32u)) break;
                }
                if (k == n) break;
            }
            if (cand <= 512u) continue;
            for (k = 0; k < n; k++) {
                u32 j, a;
                t = (cand + (k / m->w) * (map1d ? m->w : 32u) + k % m->w) & 0x3FFu;
                a = 0x06010000u + t * 32u;
                for (j = 0; j < 32u; j += 2u) ST16(a + j, (u32)m->right[k * 32u + j] | ((u32)m->right[k * 32u + j + 1u] << 8));
                used[t >> 3] |= (u8)(1u << (t & 7u));
            }
            ST16(0x07000002u + i * 8u, a1 & ~0x1000u);
            ST16(0x07000004u + i * 8u, (a2 & ~0x3FFu) | cand);
            break;
        }
    }
}

/* called by the BIOS LZ77 routines after decompressing src into dst */
void rt_mods_decompressed(u32 src, u32 dst, u32 size)
{
    const rt_prompt_edit *e;
    if (!g_rt_ngage_prompts) return;
    btn_patch(dst, size);
    for (e = g_rt_prompt_edits; e->src; e++) {
        u32 a, v;
        if (e->src != src || e->offset >= size) continue;
        a = dst + e->offset;
        v = LD16(a & ~1u);
        if (a & 1u) {
            u32 shift = 8u + (e->high ? 4u : 0u);
            v = (v & ~(0xFu << shift)) | ((u32)e->value << shift);
        } else {
            u32 shift = e->high ? 4u : 0u;
            v = (v & ~(0xFu << shift)) | ((u32)e->value << shift);
        }
        ST16(a & ~1u, v);
    }
}

/* --- title menu "Exit" ----------------------------------------------------------
 *
 * The title menu (New / Language, plus Continue with a save) is a script
 * wait at 0x080D24A7; the selected row is the byte at 0x02004539
 * (Continue 1, New 3, Language 5) and the game clamps at Language.
 *
 * Exit is a fourth row (7).  Down on Language selects it: the selection byte
 * is set to 7, so the game's own star cursor moves to the new row and
 * Language loses its highlight.  While Exit is selected the runtime keeps
 * A / START / UP away from the game (the script has no row 7): UP returns to
 * Language, A or START saves and leaves the application.  The label is drawn
 * on the panel by rt_mods_overlay(), below the 160 GBA lines: in the
 * letterbox bar or in the extended area, the same panel rows in both modes.
 */
#define TITLE_WAIT_SCRIPT 0x080D24A7u
#define TITLE_SELECTION   0x02004539u
#define ROW_LANGUAGE      5u
#define ROW_EXIT          7u

int g_rt_ngage_exit_entry = 1;
static int s_exit_selected;
static int s_on_title;
static u32 s_prev_keys;
static u32 s_mask;          /* keys hidden from the game this frame */
static u32 s_held_mask;     /* keys we consumed: hidden until released */
static int s_exit_requested;

int rt_mods_title_menu(void) { return s_on_title; }
int rt_mods_exit_selected(void) { return s_on_title && s_exit_selected; }

u32 rt_mods_keys(u32 keys)
{
    return keys & ~(s_mask | s_held_mask);
}

void rt_mods_frame(void)
{
    u32 keys = rt_platform_keys();
    u32 pressed = keys & ~s_prev_keys;
    s_prev_keys = keys;
    s_mask = 0;
    s_held_mask &= keys;    /* released keys reach the game again */
    s_on_title = g_rt_ngage_exit_entry && LD32(0x03002C60u) == TITLE_WAIT_SCRIPT;
    if (!s_on_title) {
        s_exit_selected = 0;
        return;
    }
    if (!s_exit_selected) {
        if ((pressed & (1u << 7)) && LD8(TITLE_SELECTION) == ROW_LANGUAGE) {
            s_exit_selected = 1;
            ST8(TITLE_SELECTION, ROW_EXIT);
            s_mask = 1u << 7;
            s_held_mask |= 1u << 7;
        }
        return;
    }
    /* Exit selected */
    s_mask = (1u << 0) | (1u << 3) | (1u << 6) | (1u << 7);
    if (pressed & (1u << 6)) {
        s_exit_selected = 0;
        s_held_mask |= 1u << 6;
        ST8(TITLE_SELECTION, ROW_LANGUAGE);
    } else if ((pressed & ((1u << 0) | (1u << 3))) && !s_exit_requested) {
        s_exit_requested = 1;
        if (g_rt_sram_dirty) rt_sram_flush();
        rt_ngage_request_exit();
    } else if (LD8(TITLE_SELECTION) != ROW_EXIT) {
        ST8(TITLE_SELECTION, ROW_EXIT);   /* keep the cursor on our row */
    }
}

/* The label, in the style of the game's menu words ("New", "Language"):
 * 2-pixel strokes, a 1-pixel dark outline around each letter and a light
 * grey border around the word; mint when plain, pink when selected.  The
 * game has no E or x in this style, so the letters are drawn here (fill
 * pixels only; outline and border are grown from them).  Cap height is 10
 * fill rows, lowercase 8 (rows 2..9), the i's dot sits above the cap line. */
#define EXIT_ROWS 12          /* fill rows -1 .. 10 */
static const char *const s_exit_fill[EXIT_ROWS] = {
    /* E        x         i   t        */
    "                 ss        ",
    "sssssss               ss   ",
    "sssssss               ss   ",
    "ss       ss  ss  ss  ssssss",
    "ss       ss  ss  ss  ssssss",
    "ssssss    ssss   ss   ss   ",
    "ssssss     ss    ss   ss   ",
    "ss         ss    ss   ss   ",
    "ss        ssss   ss   ss   ",
    "sssssss  ss  ss  ss   sssss",
    "sssssss  ss  ss  ss    ssss",
    "                           ",
};
#define EXIT_W 33
#define EXIT_H (EXIT_ROWS + 4)
static u8 s_exit_mask[EXIT_H][EXIT_W];    /* 0 none, 1 border, 2 outline, 3 fill */

static void build_exit_label(void)
{
    int x, y, dx, dy;
    if (s_exit_mask[2][2]) return;
    for (y = 0; y < EXIT_ROWS; y++)
        for (x = 0; s_exit_fill[y][x] && x + 2 < EXIT_W; x++)
            if (s_exit_fill[y][x] == 's') s_exit_mask[y + 2][x + 2] = 3;
    for (y = 0; y < EXIT_H; y++)
        for (x = 0; x < EXIT_W; x++) {
            if (s_exit_mask[y][x]) continue;
            for (dy = -1; dy <= 1; dy++)
                for (dx = -1; dx <= 1; dx++) {
                    int yy = y + dy, xx = x + dx;
                    if (yy >= 0 && yy < EXIT_H && xx >= 0 && xx < EXIT_W && s_exit_mask[yy][xx] == 3)
                        s_exit_mask[y][x] = 2;
                }
        }
    for (y = 0; y < EXIT_H; y++)
        for (x = 0; x < EXIT_W; x++) {
            if (s_exit_mask[y][x]) continue;
            for (dy = -1; dy <= 1; dy++)
                for (dx = -1; dx <= 1; dx++) {
                    int yy = y + dy, xx = x + dx;
                    if (yy >= 0 && yy < EXIT_H && xx >= 0 && xx < EXIT_W && s_exit_mask[yy][xx] == 2)
                        s_exit_mask[y][x] = 1;
                }
        }
}

u16 rt_scale_color(u32 bgr555);

static void plot(u16 *panel, int pitch, int x, int y, u16 c)
{
    if (x >= 0 && x < 176 && y >= 0 && y < 208) panel[y * pitch + x] = c;
}

/* the game's star cursor (hidden while Exit is selected), drawn from OAM data */
static u32 s_star_a0, s_star_a1, s_star_a2;
static int s_star_saved;

static void draw_star(u16 *panel, int pitch, int px, int py)
{
    static const u8 dims[3][4][2] = {
        { { 8, 8 }, { 16, 16 }, { 32, 32 }, { 64, 64 } },
        { { 16, 8 }, { 32, 8 }, { 32, 16 }, { 64, 32 } },
        { { 8, 16 }, { 8, 32 }, { 16, 32 }, { 32, 64 } } };
    u32 shape = (s_star_a0 >> 14) & 3u, sz = (s_star_a1 >> 14) & 3u;
    u32 base = s_star_a2 & 0x3FFu, pb = (s_star_a2 >> 12) & 15u;
    int map1d = (LD16(0x04000000u) & 0x40u) != 0, w, h, x, y;
    if (!s_star_saved || shape == 3u || (s_star_a0 & 0x2000u)) return;
    w = dims[shape][sz][0];
    h = dims[shape][sz][1];
    for (y = 0; y < h; y++)
        for (x = 0; x < w; x++) {
            u32 tile = base + (u32)(y >> 3) * (map1d ? (u32)(w >> 3) : 32u) + (u32)(x >> 3);
            u32 addr = 0x10000u + (tile & 0x3FFu) * 32u + (u32)(y & 7) * 4u + (u32)((x & 7) >> 1);
            u32 idx = (g_rt_vram[addr] >> ((x & 1) * 4)) & 15u;
            if (idx) plot(panel, pitch, px + x, py + y, rt_scale_color(*(const u16 *)(g_rt_pal + 0x200u + (pb * 16u + idx) * 2u)));
        }
}

void rt_mods_overlay(u16 *panel, int pitch)
{
    /* plain: mint fill, grey outline; selected: pink fill, black outline */
    u16 col[4];
    int x, y, ox = 22, oy = 167;
    extern int rt_view_exit_pos(int *x, int *y);
    if (!s_on_title) return;
    rt_view_exit_pos(&ox, &oy);   /* portrait title layout; else the bar below */
    build_exit_label();
    col[1] = rt_scale_color(0x6318u);                                /* 198,198,198 */
    col[2] = rt_scale_color(s_exit_selected ? 0x0000u : 0x4210u);    /* black / 132,132,132 */
    col[3] = rt_scale_color(s_exit_selected ? 0x4C9Cu : 0x6BB6u);    /* 231,33,156 / 181,239,214 */
    for (y = 0; y < EXIT_H; y++)
        for (x = 0; x < EXIT_W; x++)
            if (s_exit_mask[y][x]) plot(panel, pitch, ox + x, oy + y, col[s_exit_mask[y][x]]);
    if (s_exit_selected) draw_star(panel, pitch, ox - 18, oy + 1);
}

/* Before a frame is drawn: while Exit is selected, show Language as
 * unselected (BG1 rows 17-18 use tiles +0x12 when highlighted) and hide the
 * game's star cursor (an OBJ at the menu's left edge); the overlay draws a
 * star next to Exit instead.  Going back up re-highlights Language. */
#define TITLE_MAP      0x0600B800u     /* BG1 screen base on the title */
#define HILITE_DELTA   0x12u
static int s_unhilited;

static void recolour_language(int to_plain)
{
    u32 row, col;
    for (row = 17; row <= 18; row++)
        for (col = 3; col <= 11; col++) {
            u32 a = TITLE_MAP + row * 64u + col * 2u;
            u32 e = LD16(a), t = e & 0x3FFu;
            if (to_plain && t >= 0x192u && t < 0x1A4u) ST16(a, e - HILITE_DELTA);
            if (!to_plain && t >= 0x180u && t < 0x192u) ST16(a, e + HILITE_DELTA);
        }
}

void rt_mods_pre_render(void)
{
    btn_split_mirrors();
    btn_fix_groups();
    if (rt_mods_exit_selected()) {
        u32 i;
        recolour_language(1);
        s_unhilited = 1;
        for (i = 0; i < 128; i++) {
            u32 a0 = LD16(0x07000000u + i * 8u), a1 = LD16(0x07000002u + i * 8u);
            if (!(a0 & 0x300u) && (a1 & 0x1FFu) < 24u && (a0 & 0xFFu) >= 120u && (a0 & 0xFFu) < 156u) {
                s_star_a0 = a0;
                s_star_a1 = a1;
                s_star_a2 = LD16(0x07000004u + i * 8u);
                s_star_saved = 1;
                ST16(0x07000000u + i * 8u, a0 | 0x200u);
            }
        }
    } else if (s_unhilited) {
        if (s_on_title) recolour_language(0);
        s_unhilited = 0;
    }
}
